    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="40" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
'"'use strict';

const DURATION = 40, STEP = 1 / 240, SEED = 42, TAU = Math.PI * 2;
const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const Q = () => new THREE.Quaternion();
const UP = V(0, 1, 0), DOWN = V(0, -1, 0);
const clamp = (x, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, x));
const lerp = (a, b, u) => a + (b - a) * u;
const phase = (t, a, b) => clamp((t - a) / (b - a));
const smooth = u => u * u * (3 - 2 * u);
const ease = (t, a, b) => smooth(phase(t, a, b));
const turn = (x, y, z) => Q().setFromEuler(new THREE.Euler(x, y, z, 'YXZ'));
const color = hex => new THREE.Color(hex).convertSRGBToLinear();

function seeded(initial) {
  let state = initial >>> 0;
  return () => {
    let n = state = (state + 0x6d2b79f5) >>> 0;
    n = Math.imul(n "'^ (n >>> 15), n | 1);
    n ''^= n + Math.imul(n ''^ (n >>> 7), n | 61);
    return ((n ''^ (n >>> 14)) >>> 0) / 4294967296;
  };
}

function hash(i, j = 0) {
  let n = (Math.imul(i + SEED, 374761393) + Math.imul(j, 668265263)) | 0;
  n = Math.imul(n ''^ (n >>> 13), 1274126177);
  return ((n ''^ (n >>> 16)) >>> 0) / 4294967296;
}

function noise(x, i) {
  const n = Math.floor(x);
  return lerp(hash(n, i), hash(n + 1, i), smooth(x - n)) * 2 - 1;
}

const groundY = (x, z) => .26 * Math.sin(.095 * x + .043 * z)
  + .18 * Math.cos(.087 * z - .049 * x) + .13 * Math.sin(.16 * z + .17 * x);
const groundAt = (x, z, offset = 0) => V(x, groundY(x, z) + offset, z);
const groundGLSL = `
  float groundHeight(vec2 p) {
    return .26*sin(dot(p,vec2(.095,.043))) + .18*cos(dot(p,vec2(-.049,.087)))
      + .13*sin(dot(p,vec2(.17,.16)));
  }
`;

const strikes = [
  { time: 5, core: 0, damage: 400, stop: .1, trauma: .45 },
  { time: 12, core: 1, damage: 600, stop: .1, trauma: .55 },
  { time: 27, core: 2, damage: 500, stop: .1, trauma: .6 },
  { time: 29.5, core: 2, damage: 500, stop: .2, trauma: 1 }
];
const footTimes = [1, 2.5, 4, 5.5];
const skyStrikes = [
  { time: 8.2, point: groundAt(65, -59), trauma: .3 },
  { time: 25, trauma: .5 },
  { time: 33, point: V(125, -12, 111), trauma: .3 }
];
const traumaEvents = [
  ...footTimes.map(time => ({ time, trauma: .25 })), ...strikes, ...skyStrikes,
  { time: 7.5, trauma: .9 }, { time: 13, trauma: .7 },
  { time: 19, trauma: .8 }, { time: 31.5, trauma: .2 }
].sort((a, b) => a.time - b.time);

function motionTime(t) {
  for (const s of strikes) {
    const age = t - s.time;
    if (age >= 0 && age < s.stop + .3) {
      return s.time + Math.max(0, age - s.stop) * ((.3 + s.stop) / .3);
    }
  }
  return t;
}

function traumaAt(t) {
  let amount = 0, previous = 0;
  for (const event of traumaEvents) {
    if (event.time > t) break;
    amount = clamp(Math.max(0, amount - .8 * (event.time - previous)) + event.trauma);
    previous = event.time;
  }
  return Math.max(0, amount - .8 * (t - previous));
}

const PELVIS = 0, SPINE = 1, CHEST = 2, HEAD = 3;
const LUA = 4, LFA = 5, LFIST = 6, RUA = 7, RFA = 8, RFIST = 9;
const LTHIGH = 10, LSHIN = 11, LFOOT = 12, RTHIGH = 13, RSHIN = 14, RFOOT = 15;
const parents = [-1, 0, 1, 2, 2, 4, 5, 2, 7, 8, 0, 10, 11, 0, 13, 14];
const releaseTimes = [32, 31.4, 30.8, 29.7, 30.2, 30.2, 30.2, 30.2, 30.2, 30.2, 32.6, 32.6, 32.6, 32.6, 32.6, 32.6];
const thighLength = 8.25, shinLength = 8.5, upperLength = 7.45, foreLength = 7.15;
const slamCenter = groundAt(.8, -8);
const sweepCenter = groundAt(4.3, -4.7);
const footTrack = [
  [[0, 38.3], [1, 32.9], [4, 20.7]], [[0, 39.4], [2.5, 26.8], [5.5, 14.5]]
];

function walkingFoot(t, side) {
  const track = footTrack[side];
  let x = track[0][1], lift = 0;
  for (let i = 1; i < track.length; i++) {
    const [time, goal] = track[i];
    const u = phase(t, Math.max(0, time - 1.08), time);
    if (u < 1) {
      x = lerp(x, goal, smooth(u));
      lift = Math.pow(Math.sin(Math.PI * u), 1.4) * 1.85;
      break;
    }
    x = goal;
  }
  x = lerp(x, side ? 12.9 : 18.5, ease(t, 8.9, 11.4));
  return groundAt(x, side ? -4.55 : 4.45, 1.15 + lift);
}

function solveJoint(root, end, lengthA, lengthB, pole) {
  const axis = end.clone().sub(root);
  const d = clamp(axis.length(), .001, lengthA + lengthB - .001);
  axis.normalize();
  const lateral = pole.clone().addScaledVector(axis, -pole.dot(axis));
  if (lateral.lengthSq() < 1e-7) lateral.set(0, 0, 1).addScaledVector(axis, -axis.z);
  lateral.normalize();
  const along = (lengthA * lengthA - lengthB * lengthB + d * d) / (2 * d);
  return root.clone().addScaledVector(axis, along)
    .addScaledVector(lateral, Math.sqrt(Math.max(0, lengthA * lengthA - along * along)));
}

function titanPose(t) {
  const p = [], q = [];
  const gait = 1 - ease(t, 5.5, 6);
  const stride = Math.sin((t - .25) * TAU / 3);
  const footWeight = footTimes.reduce((total, hit) => total
    + Math.exp(-Math.pow((t - hit - .05) / .17, 2)) * .58, 0);
  const windup = ease(t, 6, 7.04) * (1 - ease(t, 7.12, 7.49));
  const planted = ease(t, 7.09, 7.5) * (1 - ease(t, 10.5, 11.85));
  const reel = ease(t, 10.5, 11.95) * (1 - ease(t, 12.14, 12.95));
  const recoil = ease(t, 12, 12.37) * (1 - ease(t, 12.35, 13));
  const kneel = ease(t, 12.35, 13) * (1 - ease(t, 15, 16));
  const sweepWind = ease(t, 17, 18.5) * (1 - ease(t, 18.5, 19.12));
  const sweepDown = ease(t, 18.25, 18.96) * (1 - ease(t, 19.18, 20.6));
  const sweepTwist = ease(t, 18.53, 19.1) * (1 - ease(t, 19.32, 20.63));
  const chestRecoil = ease(t, 25, 25.18) * (1 - ease(t, 25.26, 26.35));
  const death = ease(t, 29.5, 32.55);
  const x = 40 - 4 * Math.min(t, 6);
  let height = 18 - gait * (.54 * Math.abs(stride) + footWeight) - .65 * windup
    - 9.2 * planted - 7.8 * sweepDown - 9.4 * death;
  const yaw = .1 * gait * stride - .39 * planted - .23 * sweepWind + .64 * sweepTwist
    + .16 * recoil - .22 * kneel + .07 * Math.sin(t * .8) * (1 - gait);
  const pitch = .045 + .105 * gait + .88 * planted + .84 * sweepDown
    - .19 * windup - .34 * recoil + .37 * kneel - .16 * chestRecoil + .61 * death;
  const roll = -.08 * gait * stride - .11 * planted + .32 * sweepDown + .17 * kneel;
  q[PELVIS] = turn(roll, yaw, pitch);
  p[PELVIS] = V(x + .95 * recoil - 1.3 * kneel, height, .46 * stride * gait - 1.4 * planted);
  const leftFoot = walkingFoot(t, 0), rightFoot = walkingFoot(t, 1);
  const hipLocal = V(.12, -.45, 3.15).applyQuaternion(q[PELVIS]);
  const kneeRest = leftFoot.clone().add(V(-8.47, .10, -.38));
  const dx = p[PELVIS].x + hipLocal.x - kneeRest.x;
  const dz = p[PELVIS].z + hipLocal.z - kneeRest.z;
  height = lerp(height, kneeRest.y + Math.sqrt(Math.max(1, thighLength ** 2 - dx * dx - dz * dz)) - hipLocal.y, kneel);
  p[PELVIS].y = height;

  const child = (index, offset, relative) => {
    const parent = parents[index];
    p[index] = offset.applyQuaternion(q[parent]).add(p[parent]);
    q[index] = q[parent].clone().multiply(relative);
  };
  child(SPINE, V(0, 5.4, 0), turn(-.04 * stride * gait, -.13 * stride * gait, -.07 * gait - .12 * planted));
  child(CHEST, V(0, 6.65, 0), turn(-.036 + .05 * windup, .08 * stride * gait + .20 * sweepTwist, -.025 - .08 * kneel));
  child(HEAD, V(-.15, 5.55, 0), turn(.06 * Math.sin(t * 1.3), .14 * Math.sin(t * .72) + .16 * planted,
    -.10 - .23 * planted - .24 * chestRecoil));

  function limb(i, origin, target, a, b, pole, terminal) {
    const delta = target.clone().sub(origin);
    if (delta.length() > a + b - .012) target = origin.clone().add(delta.setLength(a + b - .012));
    const joint = solveJoint(origin, target, a, b, pole);
    p[i] = origin;
    q[i] = Q().setFromUnitVectors(DOWN, joint.clone().sub(origin).normalize());
    p[i + 1] = V(0, -a, 0).applyQuaternion(q[i]).add(p[i]);
    q[i + 1] = Q().setFromUnitVectors(DOWN, target.clone().sub(p[i + 1]).normalize());
    p[i + 2] = V(0, -b, 0).applyQuaternion(q[i + 1]).add(p[i + 1]);
    q[i + 2] = terminal(q[i + 1]);
  }

  for (const side of [0, 1]) {
    const sign = side ? -1 : 1;
    const hip = V(.12, -.45, sign * 3.15).applyQuaternion(q[PELVIS]).add(p[PELVIS]);
    const front = V(-1, 0, sign * .16).lerp(kneeRest.clone().sub(hip), side ? 0 : kneel);
    limb(side ? RTHIGH : LTHIGH, hip, side ? rightFoot : leftFoot, thighLength, shinLength, front,
      () => turn(.03 * sign, yaw * .22 + sign * .13, 0));

    const shoulder = V(-.1, .05, sign * 7.25).applyQuaternion(q[CHEST]).add(p[CHEST]);
    const swing = Math.sin((t - .52) * TAU / 3);
    const hand = V(1.3 + sign * 3.45 * swing * gait, -13.45 + .45 * Math.sin(t * 1.1 + sign), sign * 2.55)
      .applyQuaternion(q[CHEST]).add(shoulder);
    if (side) {
      hand.lerp(V(13, 41.2, -10), windup);
      hand.lerp(slamCenter.clone().add(V(0, 1.65, 0)), planted);
      hand.lerp(V(5.7, 31.2, -11.6), reel);
      hand.lerp(V(10.4, 5.1, -10), kneel * .74);
    } else {
      hand.lerp(V(22, 8, 13.5), sweepWind);
      const u = phase(t, 18.5, 19.3), angle = lerp(1.36, 3.94, u);
      const sweep = V(14 + 11.9 * Math.cos(angle), 2.0 + .55 * Math.pow((u - .61) / .61, 2),
        2.7 + 11.7 * Math.sin(angle));
      hand.lerp(sweep, sweepDown);
      hand.lerp(V(6.1, 3.4, 9.2), kneel * .9);
    }
    limb(side ? RUA : LUA, shoulder, hand, upperLength, foreLength, V(1, .26 + .55 * windup, .81 * sign),
      lower => lower.clone().slerp(turn(0, yaw, 0), .31));
  }
  return { p, q };
}

const bonePoint = (pose, bone, x, y, z) => V(x, y, z).applyQuaternion(pose.q[bone]).add(pose.p[bone]);
const coreSpecs = [[LSHIN, -1.75, -.18, -.12], [RUA, -1.78, .30, -1.38], [CHEST, -2.23, .48, .15]];
const coreAt = (pose, i) => bonePoint(pose, ...coreSpecs[i]);
skyStrikes[1].point = bonePoint(titanPose(25), HEAD, 0, 2.85, 0);

function boneCharge(t, i) {
  if (t >= releaseTimes[i]) return 0;
  if (t >= 12 && t < 16) return .4;
  if ((t >= 6 && t < 7.73) || (t >= 17 && t < 19.3)) return 1.6;
  return 1;
}

function path(a, b, va, vb, t, start, end) {
  const u = phase(t, start, end), u2 = u * u, u3 = u2 * u, duration = end - start;
  return a.clone().multiplyScalar(2 * u3 - 3 * u2 + 1).addScaledVector(b, 3 * u2 - 2 * u3)
    .addScaledVector(va, (u3 - 2 * u2 + u) * duration).addScaledVector(vb, (u3 - u2) * duration);
}

const ropeSpecs = [
  { fire: 3, attach: 3.3, end: 5.6, bone: LSHIN, local: [-1.19, -3.45, .035] },
  { fire: 9, attach: 9.3, end: 12.4, bone: RFA, local: [-1.12, -4.34, -.38] },
  { fire: 23.5, attach: 23.8, end: 31.53, bone: CHEST, local: [-2.53, 2.1, 1.15] }
];
const landingOne = groundAt(11, 6.8, .83);
const hunterSlamBait = groundAt(slamCenter.x, slamCenter.z, .83);
const launchTwo = groundAt(5.3, -12.5, .82);
const landingTwo = groundAt(-2, -13.6, .83);
const sweepVictim = groundAt(sweepCenter.x, sweepCenter.z, .83);
const landingThree = groundAt(6.3, -4.3, .82);
const aftermath = groundAt(2.6, -6.9, .82);

function firstSwing(t, pose) {
  const u = phase(t, 3.3, 5), angle = .04 + TAU * 1.015 * u;
  const y = lerp(-7.0, -.46, smooth(u));
  // The surface arc and its free tangent leg share one fixed length.
  const radius = 1.13, horizontal = Math.sqrt(9.5 ** 2 - (y + 3.45) ** 2);
  let lo = radius + .025, hi = horizontal + radius;
  for (let i = 0; i < 12; i++) {
    const r = (lo + hi) * .5, tangent = Math.acos(radius / r);
    const consumed = angle < tangent
      ? Math.hypot(r - radius * Math.cos(angle), radius * Math.sin(angle))
      : Math.sqrt(r * r - radius * radius) + radius * (angle - tangent);
    if (consumed > horizontal) hi = r;
    else lo = r;
  }
  const wrist = bonePoint(pose, LSHIN, -((lo + hi) * .5) * Math.cos(angle), y, ((lo + hi) * .5) * Math.sin(angle));
  wrist.y = Math.max(wrist.y, groundY(wrist.x, wrist.z) + .95);
  const approach = coreAt(pose, 0).sub(wrist).normalize();
  return wrist.addScaledVector(approach, -.19).add(V(0, -.39, 0));
}

function secondSwing(t, pose) {
  const u = phase(t, 9.3, 12), rise = ease(t, 10.5, 12);
  const anchor = bonePoint(pose, RFA, ...ropeSpecs[1].local);
  const hanging = anchor.clone().add(V(-2.3 - .8 * Math.sin(u * Math.PI), -3.65 + .6 * Math.sin(u * TAU), -4.05));
  hanging.y = Math.max(groundY(hanging.x, hanging.z) + .83, hanging.y);
  return hanging.lerp(coreAt(pose, 1).add(V(-.9, -1.15, -.63)), rise);
}

function thirdSwing(t, pose) {
  const anchor = bonePoint(pose, CHEST, ...ropeSpecs[2].local);
  if (t < 27) {
    const u = phase(t, 23.8, 27);
    const tilt = lerp(.60, 1.82, smooth(u)), sweep = lerp(-.77, .02, smooth(u));
    const length = lerp(17.5, 1.86, ease(t, 24.45, 27));
    const a = V(-Math.sin(tilt) * Math.cos(sweep), -Math.cos(tilt), Math.sin(tilt) * Math.sin(sweep));
    const pendulum = anchor.addScaledVector(a, length).add(V(0, -.42, 0));
    const knife = coreAt(pose, 2).add(V(-1.2, -.93, -.46));
    return pendulum.lerp(knife, ease(t, 26.05, 27));
  }
  const u = phase(t, 27, 29.5);
  return coreAt(pose, 2).add(V(-1.2 - 2.5 * Math.sin(Math.PI * u), -.93 - 2.95 * Math.sin(Math.PI * u),
    lerp(-.46, .86, smooth(u)) - .55 * Math.sin(TAU * u)));
}

let ragdoll, collapseAnchorRock;
const getUpRoot = V();
const t1Attach = firstSwing(3.3, titanPose(3.3));
const t2Attach = secondSwing(9.3, titanPose(9.3));
const t3Attach = thirdSwing(23.8, titanPose(23.8));
const retreatOne = groundAt(-10.2, 1.5, .83);
const retreatSlam = groundAt(-10.4, -17.6, .83);

function hunterRoot(t, pose) {
  if (t < 3.3) return path(groundAt(-40, 10, .83), t1Attach, V(12, 0, 1), V(5, 1.1, -4), t, 0, 3.3);
  if (t < 5) return firstSwing(t, pose);
  if (t < 5.6) return firstSwing(5, titanPose(5.6)).add(V(-2.6, -2.4, 3.9).multiplyScalar(ease(t, 5, 5.6)))
    .lerp(firstSwing(5, pose).add(V(-2.6, -2.4, 3.9).multiplyScalar(ease(t, 5, 5.6))), 1 - ease(t, 5.4, 5.6));
  if (t < 6.08) {
    const takeoff = firstSwing(5, titanPose(5.6)).add(V(-2.6, -2.4, 3.9));
    return path(takeoff, landingOne, V(-4, -3, 4), V(-8, 0, -3), t, 5.6, 6.08);
  }
  if (t < 6.5) return path(landingOne, hunterSlamBait, V(-8, 0, -3), V(-12, 0, -10), t, 6.08, 6.5);
  if (t < 7.53) return path(hunterSlamBait, retreatSlam, V(-12, 0, -10), V(0, 0, -1), t, 6.5, 7.53);
  if (t < 9) return path(retreatSlam, launchTwo, V(0, 0, -1), V(7, 0, 4), t, 7.53, 9);
  if (t < 9.3) return path(launchTwo, t2Attach, V(7, 0, 4), V(0, 0, 0), t, 9, 9.3);
  if (t < 12.4) return secondSwing(t, pose);
  if (t < 13.5) return path(secondSwing(12.4, titanPose(12.4)), landingTwo, V(-5, -1.5, -2), V(-5, -21, -3), t, 12.4, 13.5);
  if (t < 15.3) return path(landingTwo, retreatOne, V(-5, 0, -3), V(-.6, 0, 5), t, 13.5, 15.3);
  if (t < 17.3) return path(retreatOne, groundAt(-7.8, 6.2, .83), V(-.6, 0, 5), V(3, 0, -1), t, 15.3, 17.3);
  if (t <= 19) return path(groundAt(-7.8, 6.2, .83), sweepVictim, V(3, 0, -1), V(7, 0, -8), t, 17.3, 19);
  if (t < 22.5) return getUpRoot.clone();
  if (t < 23.8) {
    const start = groundAt(t3Attach.x - 9.2, t3Attach.z - 3.0, .82);
    if (t < 23.5) return path(getUpRoot, start, V(), V(12, 2, 4), t, 22.5, 23.5);
    return path(start, t3Attach, V(12, 2, 4), V(2.3, 2, 0), t, 23.5, 23.8);
  }
  if (t <= 29.5) return thirdSwing(t, pose);
  if (t < 31.5) {
    const u = phase(t, 29.5, 31.5);
    const root = thirdSwing(29.5, titanPose(29.5)).lerp(landingThree, u * u * (.68 + .32 * u));
    root.z -= 1.1 * Math.sin(u * Math.PI);
    return root;
  }
  if (t < 32.94) return path(landingThree, aftermath, V(-4.6, 0, -3), V(), t, 31.5, 32.94);
  return aftermath.clone();
}

function hunterVelocity(t) {
  const a = clamp(t - .015, 0, DURATION), b = clamp(t + .015, 0, DURATION);
  return hunterRoot(b, titanPose(b)).sub(hunterRoot(a, titanPose(a))).multiplyScalar(1 / (b - a));
}

const HIPS = 0, BODY = 1, MASK = 2, LSH = 3, LEL = 4, LWR = 5, RSH = 6, REL = 7, RWR = 8;
const LHIP = 9, LKNEE = 10, LANK = 11, RHIP = 12, RKNEE = 13, RANK = 14;
const RAG_COUNT = 15;

function animatedHunter(t, pose, rising = false, velocityHint = null) {
  const root = hunterRoot(t, pose), velocity = velocityHint || hunterVelocity(t);
  const speed = Math.hypot(velocity.x, velocity.z);
  const tether = ropeSpecs.find(r => t >= r.fire - .10 && t < r.end);
  const anchor = tether && bonePoint(pose, tether.bone, ...tether.local);
  const target = coreAt(pose, t < 6 ? 0 : t < 16 ? 1 : 2);
  const heading = velocity.clone().setY(0);
  if (heading.length() < 1.5) heading.copy(rising || t > 32.8 ? V(1, 0, .23) : target.clone().sub(root).setY(0));
  heading.normalize();
  const air = smooth(clamp((root.y - groundY(root.x, root.z) - 1) * 1.13));
  if (tether && t > tether.attach && air > .1) {
    heading.lerp(target.clone().sub(root).setY(0).normalize(), air * .84).normalize();
  }
  const side = V(-heading.z, 0, heading.x), cadence = TAU * (2.3 * t + .11 * Math.sin(t * .8));
  const effort = clamp(speed / 9) * (1 - air);
  const rollU = phase(t, 31.5, 32.2), rolling = Math.sin(Math.PI * rollU);
  const parts = [];
  const get = rising ? 1 - ease(t, 21.5, 22.45) : 0;
  root.y += .055 * effort * (1 - Math.cos(2 * cadence)) + .018 * Math.sin(t * 4) - .19 * rolling - .42 * get;
  const bodyUp = UP.clone().addScaledVector(heading, .42 * effort - .30 * air + get * 1.18).normalize();
  parts[HIPS] = root;
  parts[BODY] = root.clone().addScaledVector(bodyUp, .46).addScaledVector(side, .025 * Math.sin(cadence) * effort);
