// Fixed-step poses are stored as Float32 snapshots. Sampling has no mutable cursor.
function readCache(cache, time, count, into = []) {
  const stride = count * 3, frame = clamp((time - cache.start) / STEP, 0, cache.steps);
  const a = Math.floor(frame), b = Math.min(a + 1, cache.steps), u = frame - a;
  for (let i = 0; i < count; i++) {
    const idx = i * 3, x = a * stride + idx, y = b * stride + idx;
    (into[i] ||= V()).set(lerp(cache.data[x], cache.data[y], u), lerp(cache.data[x + 1], cache.data[y + 1], u),
      lerp(cache.data[x + 2], cache.data[y + 2], u));
  }
  return into;
}

function snapshot(out, index, points) {
  let j = index * points.length * 3;
  for (const p of points) {
    out[j++] = p.x; out[j++] = p.y; out[j++] = p.z;
  }
}

function constrain(a, b, distance, wa, wb) {
  const x = b.x - a.x, y = b.y - a.y, z = b.z - a.z;
  const length = Math.sqrt(x * x + y * y + z * z);
  if (length < 1e-8) return;
  const f = (1 - distance / length) / (wa + wb), u = f * wa, v = f * wb;
  a.x += x * u; a.y += y * u; a.z += z * u;
  b.x -= x * v; b.y -= y * v; b.z -= z * v;
}

