function bolt(a,b,steps,jitter,id,tick,r,g,blue,width){
  const axis=b.clone().sub(a).normalize();
  const normal=axis.clone().cross(UP);
  if(normal.lengthSq()<.001)normal.set(1,0,0);
  normal.normalize();
  const binormal=axis.clone().cross(normal).normalize();
  let previous=a;
  for(let k=1;k<=steps;k++){
    const u=k/steps;
    const fade=Math.sin(Math.PI*u)*jitter;
    const point=a.clone().lerp(b,u)
      .addScaledVector(normal,fade*(hash(id+k*771,tick)*2-1))
      .addScaledVector(binormal,fade*(hash(id+k*113,tick+176)*2-1));
    const energy=.79+.35*hash(id+k*91,tick+64);
    segment(previous,point,r*energy,g*energy,blue*energy,width);
    previous=point;
  }
}

const arcLinks=rockClusters.map((members,i)=>{
  const candidates=[];
  members.forEach((a,ai)=>members.forEach((b,bi)=>{
    if(ai>=bi)return;
    candidates.push({a,b,d:a.rest.distanceTo(b.rest)});
  }));
  candidates.sort((a,b)=>a.d-b.d);
  const chosen=[], covered=new Set();
  for(const c of candidates) {
    if(covered.has(c.a.id)&&covered.has(c.b.id))continue;
    chosen.push(c);
    covered.add(c.a.id); covered.add(c.b.id);
    if(chosen.length===5)break;
  }
  const parent=parents[i];
  if(parent>=0){
    let nearest=Infinity,pair;
    for(const a of members)for(const b of rockClusters[parent]){
      const d=floatingRock(a,0,titanPose0).distanceToSquared(floatingRock(b,0,titanPose0));
      if(d<nearest){nearest=d;pair={a,b};}
    }
    chosen.unshift(pair);
  }
  return [...chosen,...candidates.filter(c=>!chosen.includes(c)).slice(0,2)];
});

function electricLink(a,b,tick,i,power,residual=false){
  const d=a.p.distanceTo(b.p);
  if(d>.01 && d<(residual?9:11)){
    const amount=(.59+.47*hash(i,tick))*power;
    const endpoint=a.p.clone().lerp(b.p,Math.min(.44,Math.max(.07,a.scale.length()*.37/d)));
    const end=b.p.clone().lerp(a.p,Math.min(.44,Math.max(.07,b.scale.length()*.37/d)));
    const jitter=lerp(.14,.73,clamp(d/7))*(.53+hash(i+9,tick)*.82);
    bolt(endpoint,end,d>4?7:5,jitter,i,tick,.30*amount,1.25*amount,2.72*amount,
      (.89+.59*hash(i+23,tick))*Math.sqrt(power));
  }
}

function buildLightning(t,mt){
  const tick=Math.floor(t*20);
