    const amount=boneCharge(t,i);
    const count=amount===0?0:amount<.5?3:amount>1?7:5;
    for(let j=0;j<count;j++){
      const {a,b}=arcLinks[i][j];
      if(boneCharge(t,b.bone)>0) electricLink(a,b,tick,331*i+j,amount);
    }
  }
  if(t>32.25&&t<37.55){
    for(let i=0;i<11;i++){
      const a=rocks[Math.floor(hash(i,102)*rocks.length)];
      if(t<a.drop.rt+a.drop.impact)continue;
      let b, nearest=8.3**2;
      for(const candidate of rocks){
        if(candidate===a||t<candidate.drop.rt+candidate.drop.impact)continue;
        const d=a.p.distanceToSquared(candidate.p);
        if(d>.42&&d<nearest){nearest=d;b=candidate;}
      }
      const faint=(1-ease(t,33.2,37.55))*(.4+.36*hash(i,tick));
      if(b && hash(i,tick>>1)>.32) electricLink(a,b,tick,2500+i,faint,true);
    }
  }
  for(let i=0;i<skyStrikes.length;i++){
    const {time,point}=skyStrikes[i], age=t-time;
    if(age<0||age>=.25)continue;
    const upper=point.clone().add(V(-10+i*11,108+i*13,-13+i*5));
    const a=point.clone().lerp(upper,.39).add(V(3.4,0,-3.1));
    const b=point.clone().lerp(upper,.72).add(V(-6.8,-1.0,7.1));
    const strength=(.54+.46*hash(tick,712+i))*(1-ease(age,.14,.25));
    const tone=[2.2*strength,4.7*strength,8.7*strength];
    bolt(point,a,15,2.4,801+i*291,tick,...tone,3.6);
    bolt(a,b,15,3.1,803+i*291,tick,...tone,3.5);
