      const fork=base.clone().add(V(noise(j+i*9,212)*24,lerp(13,34,hash(j,270)),noise(j+i*9,211)*28));
      bolt(base,fork,12,2.95,i*331+j*1018,tick,.84*strength,1.91*strength,4.3*strength,1.45);
    }
  }
  for(let i=0;i<ropeSpecs.length;i++){
    const r=ropeSpecs[i], age=mt-r.fire;
