const COUNTDOWN='COUNTDOWN', PLAYING='PLAYING', PAUSED='PAUSED', REFIRE_HOLD='REFIRE_HOLD', ENDED='ENDED';
let state=COUNTDOWN, simTime=0, playbackSpeed=1;
let countdownElapsed=0, holdElapsed=0, lastWall=null;
const countdown=document.getElementById('countdown');
const scrubber=document.getElementById('scrubber');
const toggle=document.getElementById('btn-toggle');
const iconPlay=document.getElementById('icon-play');
const iconPause=document.getElementById('icon-pause');
const pills=[...document.querySelectorAll('.speed-pill')];

function hideCountdown(){
  countdown.style.display='none';
  countdown.textContent='';
}
function enter(next){
  state=next;
  const animating=next===PLAYING||next===COUNTDOWN||next===REFIRE_HOLD;
  iconPause.style.display=animating?'':'none';
  iconPlay.style.display=animating?'none':'';
  toggle.setAttribute('aria-label',animating?'Pause':'Play');
  if(next"'!==COUNTDOWN)hideCountdown();
  sound.state(next===PLAYING);
}
function showTime(reset=false){
  scrubber.value=reset?'"'0':simTime.toFixed(3);
  renderAt(simTime);
}
toggle.addEventListener('click',()=>{
  if(state===PLAYING||state===COUNTDOWN||state===REFIRE_HOLD){
    enter(PAUSED);
  }else if(state===ENDED){
    simTime=0;
    enter(PLAYING);
    showTime(true);
  }else enter(PLAYING);
  lastWall=performance.now();
});
document.getElementById('btn-refire').addEventListener('click',()=>{
  simTime=0;
  holdElapsed=0;
  enter(REFIRE_HOLD);
  showTime(true);
  lastWall=performance.now();
});
scrubber.addEventListener('input',()=>{
  simTime=clamp(parseFloat(scrubber.value),0,DURATION);
  enter(PAUSED);
  renderAt(simTime);
});
scrubber.addEventListener('pointerdown',()=>{
  if(state===PLAYING)enter(PAUSED);
});
for(const pill of pills)pill.addEventListener('click',()=>{
  playbackSpeed=Number(pill.dataset.speed);
  for(const p of pills){
    p.classList.toggle('is-active',p===pill);
    p.setAttribute('aria-checked',String(p===pill));
  }
});
window.addEventListener('resize',()=>{
  resize();
  renderAt(simTime);
});

function update(wall){
  const dt=lastWall===null?0:Math.min(.1,Math.max(0,(wall-lastWall)/1000));
  lastWall=wall;
  if(state===COUNTDOWN){
    countdownElapsed+=dt;
    if(countdownElapsed>=3)enter(PLAYING);
    else{
      const digit=String(3-Math.floor(countdownElapsed));
      if(countdown.textContent"'!==digit)countdown.textContent=digit;
      countdown.style.display='"'block';
    }
  }else if(state===REFIRE_HOLD){
    holdElapsed+=dt;
    if(holdElapsed>=1)enter(PLAYING);
  }
  if(state===PLAYING&&dt>0){
    const previous=simTime;
    simTime=Math.min(DURATION,simTime+dt*playbackSpeed);
    showTime();
    sound.forward(previous,simTime,playbackSpeed);
    if(simTime>=DURATION)enter(ENDED);
  }
  window.requestAnimationFrame(update);
}
hideCountdown();
resize();
showTime(true);
window.requestAnimationFrame(update);
</script>
